NativeStockContract.cs.source:
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Potions;
using MegaCrit.Sts2.Core.Runs;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private async Task AssertClosedPotionStockAsync(CombatState live, Player player)
    {
        foreach (var relic in player.Relics.ToArray()) await RelicCmd.Remove(relic);
        await ClearPlayerPilesAsync(player);
        for (int i = 0; i < 8; i++)
            await InjectCardAsync(live, player, new() { CardId = "BLOODLETTING", Pile = "Hand" });
        await InjectCardAsync(live, player, new() { CardId = "STRIKE_IRONCLAD", Pile = "Hand" });
        foreach (var potion in player.PotionSlots.ToArray()) potion?.Discard();
        InjectPotionForTest(player, "ENERGY_POTION");
        InjectPotionForTest(player, "SWIFT_POTION");
        SetEnergy(player, 3);
        await CreatureCmd.SetCurrentHp(live.Enemies.Single(), 6);
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        if (!root.UsesComponentHealingCertificate || root.ClosedPotionInventory is not { } stock)
            throw new InvalidOperationException("Closed stock source rejected: " + root.ComponentHealingRejection);
        var parent = root.ForkSimulator();
        string before = DescribeContinuationContractState(parent, root, player);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        int? Cost(CombatPredictionSimulator sim, int k)
            => stock.MinimumExplicitCost(sim, player, k,
                StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, player, 0));
        CombatPredictionSimulator Use(CombatPredictionSimulator from, int slot)
        {
            var child = from.Fork();
            var combat = (SimulatedCombatState)child.State.CombatState;
            var potion = combat.GetPotionAtSlot(player, slot)!;
            int start = child.History.Entries.Count;
            combat.BeginActionChoices((IReadOnlyList<PlanCardChoice>?)null);
            try
            {
                if (!PotionExecutionSupport.Prepare(child, combat, potion, slot, player.Creature)
                    || !PotionExecutionSupport.Complete(child, combat, potion, player.Creature, null,
                        start, new ForkableSet<uint>())
                    || !CombatBeamSolver.SettleReplayActionBoundary(child, combat))
                    throw new InvalidOperationException("Potion stock use suspended.");
            }
            finally { combat.EndActionChoices(); }
            return child;
        }
        CombatPredictionSimulator first;
        CombatPredictionSimulator both;
        using (SimulationNotificationIsolation.Enter())
        {
            if (Cost(parent, 1) != 9 || Cost(parent, 2) != 27 || Cost(parent, 3) is not null)
                throw new InvalidOperationException("Initial distinct costs or insufficient stock fallback failed.");
            first = Use(parent, 1);
            both = Use(first, 0);
            var reverse = Use(Use(parent, 0), 1);
            if (Cost(first, 1) != 18 || Cost(first, 2) != 27 || Cost(both, 2) != 27
                || Cost(reverse, 2) != 27 || Cost(parent, 2) != 27)
                throw new InvalidOperationException("Use-order lower bound or parent ownership failed.");
            for (int i = 0; i < 16; i++)
            {
                var fork = parent.Fork();
                if (Cost(fork, 2) != 27 || Cost(Use(fork, i % 2), 2) != 27)
                    throw new InvalidOperationException("Fork stock proof differed.");
            }
            var automatic = parent.Fork();
            var automaticCombat = (SimulatedCombatState)automatic.State.CombatState;
            automaticCombat.ConsumePotion(automaticCombat.GetPotionAtSlot(player, 0)!);
            if (Cost(automatic, 1) != 18 || Cost(automatic, 2) is not null)
                throw new InvalidOperationException("Automatic use spent explicit quota or left consumable stock.");
            var refilled = first.Fork();
            ((SimulatedCombatState)refilled.State.CombatState).TryProcurePotion(player, ModelDb.Potion<SwiftPotion>());
            if (Cost(refilled, 2) is not null)
                throw new InvalidOperationException("Same-ID refill was accepted after consumption.");
            var free = first.Fork();
            ((SimulatedCombatState)free.State.CombatState).TryProcurePotion(player,
                ModelDb.Potion<EnergyPotion>(), freeFromEntropic: true);
            if (Cost(free, 2) is not null || ClosedInitialPotionInventory.Capture(free, player, false) is not null)
                throw new InvalidOperationException("Unexpected free acquisition was accepted.");
            var unknown = parent.Fork();
            unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Alchemize>(), player),
                PileType.Exhaust, player, resultKind: CardGenerationResultKind.Fixed);
            if (Cost(unknown, 2) is not null)
                throw new InvalidOperationException("Unknown branch source accepted.");
            var active = parent.Fork();
            ((SimulatedCombatState)active.State.CombatState).SetAmount<MegaCrit.Sts2.Core.Models.Powers.RegenPower>(player.Creature, 5);
            if (Cost(active, 2) != 27
                || StrategicHpRecoveryBound.ComponentHealingUpperBound(active, player, 0,
                    includePotionHealing: false, maximumExplicitPotionUses: 0) != 15)
                throw new InvalidOperationException("Inventory proof changed existing regeneration.");
        }
        var policy = SolverController.CaptureSearchPolicy(SolverSettings.Capture(), live, false, null) with
        {
            FixedBudget = true, VerifyIncrementalSearch = true, MaxDegreeOfParallelism = 2,
            DetailedDiagnostics = false, MeasurePhasePerformance = false, BudgetOverrideMilliseconds = null,
            StopAtAcceptableBattleHpLoss = false, UseNoveltyPortfolio = false,
            PotionPolicy = SolverPotionPolicy.Smart, PotionStrategy = new(SolverPotionPolicy.Smart, []),
            RelicTargets = [], PrimaryIncumbents = new(),
        };
        policy = policy with { Profile = policy.Profile with
            { BeamWidth = 8, MaxExpandedNodes = 200, SoftTimeBudgetMilliseconds = 10000 } };
        int pruned = await Task.Run(() => CombatBeamSolver.AssertClosedStockConsumerForTesting(root,
            SolverDisplayNames.Capture(live), BattleDamageTracker.Observe(live), policy));
        if (DescribeContinuationContractState(parent, root, player) != before
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Proof mutated parent, live or RNG.");
        using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(15));
        foreach (var pair in new[] { (Slot: 1, Sim: first), (Slot: 0, Sim: both) })
        {
            var potion = player.GetPotionAtSlotIndex(pair.Slot)!;
            string expected = ContinuationStamp.CapturePredicted(player, pair.Sim, root.StartTurnNumber,
                root.Forecast, root.StartTurnNumber).StateText;
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is UsePotionAction use && use.PotionIndex == (uint)pair.Slot
                    && ReferenceEquals(use.Player, player),
                () => potion.EnqueueManualUse(player.Creature), deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
            if (ContinuationStamp.CaptureLive(live).StateText != expected)
                throw new InvalidOperationException("Native stock potion complete state differs.");
        }
        await InjectCardAsync(live, player, new() { CardId = "ALCHEMIZE", Pile = "Exhaust", TreatAsDeckCard = true });
        if (CombatRootSnapshot.Capture(live).ClosedPotionInventory is not null
            || Cost(parent, 2) != 27 || DescribeContinuationContractState(parent, root, player) != before)
            throw new InvalidOperationException("Unknown permanent/exhaust root or immutable stock ownership failed.");
        _completedChecks.Add($"ClosedPotionStock:IndependentSourceClosure:Distinct9Plus18:BothUseOrders:AutomaticExcluded:16Forks:SameIdRefillAndFreeRefused:UnknownInitialAndBranchExhaustRefused:ActiveRegenPreserved:CompleteP0Witness:ActualExtraPrunes={pruned}:TwoNativePotionFullStates:ParentLiveRngIsolation");
    }
}

internal sealed partial class CombatBeamSolver
{
    internal static int AssertClosedStockConsumerForTesting(CombatRootSnapshot root,
        SolverDisplayNames names, BattleDamageSnapshot damage, SearchPolicySnapshot policy)
    {
        using var isolation = SimulationNotificationIsolation.Enter();
        var witnessMember = new CombatBeamSolver(root, names, damage, policy,
            potionPolicyOverride: SolverPotionPolicy.Disabled);
        SearchNode winner = CreateOpeningSearchSeed(witnessMember.Replay([]));
        for (int i = 0; i < 8; i++)
            winner = witnessMember.CostChildForTesting(winner, witnessMember.PrepareCardActions(winner)
                .First(action => action.Action.CardId == "BLOODLETTING").Action);
        winner = witnessMember.CostChildForTesting(winner, witnessMember.PrepareCardActions(winner)
            .First(action => action.Action.CardId == "STRIKE_IRONCLAD").Action);
        if (!winner.IsTerminal || winner.Snapshot.PlayerDead || winner.Snapshot.HasRisk
            || !witnessMember.TightenPrimarySearchIncumbentAtTurnLayer([winner], 0)
            || witnessMember._primaryIncumbent is not { } witnessed)
            throw new InvalidOperationException("No actual complete qualified P0 witness.");
        var baseline = new PotionFreePolicyBaseline(true, witnessed.StrategicHpDeficit,
            winner.Snapshot.PlayerHp, winner.Turn);
        var member = new CombatBeamSolver(root, names, damage, policy,
            potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
            potionFreePolicyBaseline: baseline, minimumPotionUses: 2, maximumPotionUses: 2,
            directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
        SearchNode seed = CreateOpeningSearchSeed(member.Replay([]));
        int heal = member.RemainingHealingPotential(seed.Snapshot);
        int lower = StrategicHpLowerBound(seed.Snapshot, member._strategicBossHpRelief, heal);
        if (member._smartPotionEligibilityHpCeiling is not { } oldCeiling || lower > oldCeiling)
            throw new InvalidOperationException($"Fixture was already denied by old floor: lower={lower}, old={member._smartPotionEligibilityHpCeiling}, witness={witnessed.StrategicHpDeficit}.");
        if (member.ApplySmartPotionEligibilityBound([seed]).Count != 0
            || member._closedStockEligibilityBranchesPruned != 1)
            throw new InvalidOperationException("Distinct stock cost did not prune the impossible exact layer.");
        var unknown = root.ForkSimulator();
        unknown.AddGeneratedCardToCombat(PredictedCard.Create(ModelDb.Card<Alchemize>(), root.PlayerIdentity),
            PileType.Exhaust, root.PlayerIdentity, resultKind: CardGenerationResultKind.Fixed);
        SearchNode unknownNode = CreateOpeningSearchSeed(member.Snapshot(unknown, root.StartTurnNumber, actionCount: 0, shufflesCrossed: 0, boundary: SearchBoundaryReason.None, processedEnemyDeaths: new ForkableSet<uint>()));
        if (member.ApplySmartPotionEligibilityBound([unknownNode]).Count != 1)
            throw new InvalidOperationException("Stock shortcut removed unknown source branch.");
        foreach (var guard in new[]
        {
            policy with { PotionPolicy = SolverPotionPolicy.Disabled },
            policy with { PotionPolicy = SolverPotionPolicy.RequireAtLeastOne },
            policy with { TheftPolicy = SolverTheftPolicy.PreserveResources },
            policy with { GrowthOpportunityTargets = GrowthOpportunityTargets.UnboundedForTesting("closed-stock") },
            policy with { RelicTargets = [new(RelicCounterId.PenNib, 2, 2, 1, 10)] },
            policy with { PotionStrategy = new(SolverPotionPolicy.Smart,
                [new(0, "ENERGY_POTION", SolverPotionDirective.Force)]) },
        })
        {
            var guarded = new CombatBeamSolver(root, names, damage, guard,
                potionPolicyOverride: SolverPotionPolicy.RequireAtLeastOne,
                potionFreePolicyBaseline: baseline, minimumPotionUses: 2, maximumPotionUses: 2,
                directSearchPurpose: DirectSearchPurpose.SmartPotionGradient);
            if (guarded._smartPotionEligibilityHpCeiling is not null)
                throw new InvalidOperationException("Stock shortcut ignored existing policy/resource guard.");
        }
        return member._closedStockEligibilityBranchesPruned;
    }
}

