                            $"SingleStepTakeover:Mode={resumeMode}:Turn={expectedTurn}:" +
                            $"DelayMs={actualDelay}:Reused=true:UnexpectedReplans=0");
                        return Observation(combatEnded: false);
                    }
                    runner.EnsureWithinDeadline();
                    await runner.NextFrameAsync();
                }
