                        }
                        runner._completedChecks.Add(
                            $"SingleStepBoundary:Turn={expectedTurn}:Surface=Hand:Selected=0:UiTurn={expectedTurn}");
                        Entry.Logger.Info(
                            $"[CombatSolver/Test] SINGLE_STEP_BOUNDARY turn={expectedTurn} " +
